from pathlib import Path
import json, sqlite3
ROOT=Path(__file__).resolve().parents[1]
def add_before(path,marker,text,token):
 s=path.read_text(encoding='utf-8')
 if token in s:return
 path.write_text(s.replace(marker,text+marker,1),encoding='utf-8')
data=json.loads((ROOT/'data/soudal_products.json').read_text(encoding='utf-8'))
db=sqlite3.connect(ROOT/'data/catalog.db')
for p in data.get('products',[]):
 image=p.get('asset_image') or p.get('image',''); docs=[{'title':'Ficha técnica Soudal','url':'/'+p['asset_doc'].lstrip('/')}] if p.get('asset_doc') else []
 variants=[{'name':v.get('color') or v.get('name') or v.get('label') or '','color':v.get('color') or v.get('name') or v.get('label') or '','label':v.get('color') or v.get('name') or v.get('label') or '','price':v.get('price',p.get('price',0))} for v in p.get('variants',[])]
 db.execute('''UPDATE products SET name=?,ref=?,brand=?,family=?,category=?,subfamily=?,price=?,price_display=?,stock=?,description=?,tech=?,image=?,gallery_json=?,docs_json=?,variants_json=?,updated_at=CURRENT_TIMESTAMP WHERE slug=?''',(p.get('name',''),p.get('ref',''),p.get('brand','Soudal'),p.get('family','Construção'),p.get('category','Colas e Selantes'),p.get('subfamily','Soudal'),float(p.get('price') or 0),p.get('price_display',''),float(p.get('stock') or 0),p.get('description',''),json.dumps(p.get('tech',[]),ensure_ascii=False),image,json.dumps([image] if image else [],ensure_ascii=False),json.dumps(docs,ensure_ascii=False),json.dumps(variants,ensure_ascii=False),p.get('slug','')))
db.commit();db.close()
pp=ROOT/'produto-wc.html'
add_before(pp,'</head>','<style id="MM_SoudalLocalV2">.mm-color-grid{display:flex;flex-wrap:wrap;gap:8px}.mm-color-btn{display:inline-flex;align-items:center;gap:8px;border:1px solid #cfd6dc;background:#fff;border-radius:10px;padding:9px 12px;font-weight:800;cursor:pointer}.mm-color-btn.active{border-color:#f28c00;box-shadow:0 0 0 2px rgba(242,140,0,.13)}.mm-color-dot{width:22px;height:22px;border-radius:50%;border:1px solid #c6ccd1;display:inline-block;box-shadow:inset 0 0 0 2px #fff}</style>','MM_SoudalLocalV2')
add_before(pp,'</body>','''<script id="MM_SoudalLocalV2">(async function(){try{if(!slug||!/^soudal-|^soudabond-/i.test(slug))return;const r=await fetch('/data/soudal_products.json?x='+Date.now(),{cache:'no-store'});if(!r.ok)return;const d=await r.json(),raw=(d.products||[]).find(x=>x.slug===slug);if(!raw)return;const vs=(raw.variants||[]).map(v=>({name:v.color||v.name||v.label||'',color:v.color||v.name||v.label||'',price:v.price})).filter(v=>v.name);P={...P,...raw,image:'/'+String(raw.asset_image||raw.image||'').replace(/^\\//,''),gallery:[raw.asset_image||raw.image].filter(Boolean).map(x=>'/'+String(x).replace(/^\\//,'')),docs:raw.asset_doc?[{title:'Ficha técnica Soudal',url:'/'+String(raw.asset_doc).replace(/^\\//,'')}]:[],variants:vs,brand:'Soudal',description:raw.description||P.description,tech:raw.tech||P.tech,price:raw.price||P.price,price_display:raw.price_display||P.price_display,sku:raw.ref||P.sku};render();setTimeout(()=>{const t=document.querySelector('.variant-title'),g=document.querySelector('.variant-grid');if(t&&g&&vs.length){t.textContent='Escolha a cor';g.className='mm-color-grid';g.innerHTML=vs.map((v,i)=>{let c=(v.color||'').toLowerCase(),bg='#fff';if(c.includes('preto'))bg='#171717';else if(c.includes('cinz'))bg='#9ca3a8';else if(c.includes('castanho'))bg='#8b5a36';else if(c.includes('terracota'))bg='#b85c43';else if(c.includes('bege'))bg='#d7c2a2';else if(c.includes('antracite'))bg='#4d5255';else if(c.includes('transpar'))bg='linear-gradient(135deg,#fff,#dfe8ef)';return `<button type="button" class="mm-color-btn ${i===0?'active':''}" onclick="selectVariant(${i});MMColor(${i})"><span class="mm-color-dot" style="background:${bg}"></span>${esc(v.name)}</button>`}).join('')}}},100)}catch(e){console.warn('Soudal local',e)}})();function MMColor(i){document.querySelectorAll('.mm-color-btn').forEach((b,k)=>b.classList.toggle('active',k===i))}</script>''','MM_SoudalLocalV2')
add_before(pp,'</body>','''<script id="MM_SoudalMoneyFix">function money(v){if(v===null||v===undefined||v==='')return '';if(typeof v==='number'&&Number.isFinite(v))return '€ '+v.toFixed(2).replace('.',',');let s=String(v).trim();let n=Number(s.replace('€','').replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)&&n>0?'€ '+n.toFixed(2).replace('.',','):s}</script>''','MM_SoudalMoneyFix')
cp=ROOT/'catalogo.html'
add_before(cp,'</body>','''<script id="MM_SoudalCatalogV2">(async function(){try{const r=await fetch('/data/soudal_products.json?x='+Date.now(),{cache:'no-store'});if(!r.ok)return;const d=await r.json(),a=d.products||[];const fix=()=>document.querySelectorAll('.product').forEach(card=>{const n=card.querySelector('h3')?.textContent?.trim(),p=a.find(x=>x.name===n);if(p?.asset_image){const im=card.querySelector('img');if(im){im.src='/'+String(p.asset_image).replace(/^\\//,'');im.onerror=null}}});setTimeout(fix,300);const old=window.load;if(typeof old==='function')window.load=async function(){const z=await old.apply(this,arguments);setTimeout(fix,100);return z}}catch(e){console.warn(e)}})();</script>''','MM_SoudalCatalogV2')
ap=ROOT/'admin.html'
add_before(ap,'</head>','<style id="MM_SoudalBOv2">.mm-sb-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mm-sb-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:14px}.mm-sb-colors{display:grid;gap:8px}.mm-sb-color{display:grid;grid-template-columns:1.5fr 1fr 42px;gap:8px}@media(max-width:800px){.mm-sb-grid{grid-template-columns:1fr}.mm-sb-color{grid-template-columns:1fr 1fr 42px}}</style>','MM_SoudalBOv2')
add_before(ap,'</body>','''<script id="MM_SoudalBOv2">(function(){let list=[],cur=null;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function open(){if(!$('#mmSoudalView'))$('.content').insertAdjacentHTML('beforeend','<section id="mmSoudalView" class="view"></section>');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$('#mmSoudalView').classList.add('active');list=await(await fetch('/api/admin/products?brand=Soudal',{cache:'no-store'})).json();cur=list[0]||null;draw()}function nav(){const n=$('.nav');if(!n||$('#mmSoudalB'))return;const b=document.createElement('button');b.id='mmSoudalB';b.textContent='🧴 Soudal';b.onclick=open;n.appendChild(b)}function draw(){const v=$('#mmSoudalView');v.innerHTML=`<div class="bo-section-head"><div><div class="eyebrow">Produtos / Soudal</div><h2>Editor Soudal</h2><p class="muted">Preço, stock, descrição, imagem local, ficha técnica, especificações e cores. Sem seleção de embalagens.</p></div><div class="actions"><select id="sbSel" class="input" style="width:auto;min-width:280px">${list.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select><button class="btn primary" id="sbSave">Guardar alterações</button></div></div><div id="sbForm" class="mm-sb-card"></div>`;$('#sbSel').value=list.indexOf(cur);$('#sbSel').onchange=e=>{cur=list[+e.target.value];form()};$('#sbSave').onclick=save;form()}function form(){const p=cur||{};$('#sbForm').innerHTML=`<div class="mm-sb-grid"><div><label class="label">Nome</label><input id="sbName" class="input" value="${esc(p.name)}"></div><div><label class="label">Referência</label><input id="sbRef" class="input" value="${esc(p.ref)}"></div><div><label class="label">Preço (€)</label><input id="sbPrice" class="input" type="number" step="0.01" value="${p.price??''}"></div><div><label class="label">Stock</label><input id="sbStock" class="input" type="number" value="${p.stock??0}"></div><div class="full"><label class="label">Descrição</label><textarea id="sbDesc" class="input" rows="4">${esc(p.description)}</textarea></div><div><label class="label">Imagem local</label><input id="sbImg" class="input" value="${esc(p.image||'')}"></div><div><label class="label">Ficha técnica local</label><input id="sbDoc" class="input" value="${esc((p.docs&&p.docs[0]&&p.docs[0].url)||'')}"></div><div class="full"><label class="label">Especificações técnicas</label><textarea id="sbTech" class="input" rows="7">${esc((Array.isArray(p.tech)?p.tech:[]).join('\\n'))}</textarea></div></div><div class="mm-sb-card"><h3>Cores disponíveis</h3><div id="sbColors" class="mm-sb-colors"></div><button id="sbAdd" class="btn">+ Adicionar cor</button></div>`;colors();$('#sbAdd').onclick=()=>{cur.variants=cur.variants||[];cur.variants.push({name:'',color:'',price:cur.price||0});colors()}}function colors(){const b=$('#sbColors');b.innerHTML=(cur.variants||[]).map((v,i)=>`<div class="mm-sb-color"><input class="input sbc" value="${esc(v.color||v.name||v.label)}" placeholder="Cor"><input class="input sbcp" type="number" step="0.01" value="${v.price??cur.price??''}" placeholder="Preço"><button class="btn danger sbr" data-i="${i}">✕</button></div>`).join('');b.querySelectorAll('.sbr').forEach(x=>x.onclick=()=>{cur.variants.splice(+x.dataset.i,1);colors()})}async function save(){cur.name=$('#sbName').value;cur.ref=$('#sbRef').value;cur.price=+$('#sbPrice').value||0;cur.price_display=cur.price?('€ '+cur.price.toFixed(2).replace('.',',')):'';cur.stock=+$('#sbStock').value||0;cur.description=$('#sbDesc').value;cur.image=$('#sbImg').value;cur.gallery=[cur.image].filter(Boolean);const doc=$('#sbDoc').value;cur.docs=doc?[{title:'Ficha técnica Soudal',url:doc}]:[];cur.tech=$('#sbTech').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);cur.variants=[...document.querySelectorAll('.sbc')].map((x,i)=>({name:x.value,color:x.value,label:x.value,price:+document.querySelectorAll('.sbcp')[i].value||cur.price}));const out=await(await fetch('/api/admin/product',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cur)})).json();alert(out.ok?'Produto Soudal guardado.':'Erro: '+(out.error||'desconhecido'));list=await(await fetch('/api/admin/products?brand=Soudal',{cache:'no-store'})).json();cur=list.find(x=>x.slug===cur.slug)||list[0];draw()}document.addEventListener('DOMContentLoaded',nav)})();</script>''','MM_SoudalBOv2')
print('Soudal V2 corrigido')
